import type { Metadata } from "next";
import { MarketDetail } from "@/components/MarketDetail";
import { impliedYes, readPool } from "@/lib/market-manifest";

/**
 * Per-market head. The share card is generated by `opengraph-image.tsx` in this same
 * segment, so the title, the numbers and the artwork are built from one manifest read.
 */
export async function generateMetadata({ params }: { params: Promise<{ id: string }> }): Promise<Metadata> {
  const { id } = await params;
  const pool = await readPool(id);
  const title = pool?.title ?? `Market #${id}`;
  const yes = Math.round(impliedYes(pool) * 100);
  const description = `${yes}% YES / ${100 - yes}% NO · binary market on Base, settled in native USDC with on-chain evidence.`;

  return {
    title,
    description,
    alternates: { canonical: `/market/${id}` },
    openGraph: {
      title,
      description,
      type: "article",
      url: `/market/${id}`,
      siteName: "Prediction Arena",
    },
    twitter: {
      card: "summary_large_image",
      title,
      description,
    },
  };
}

export default async function MarketPage({ params }: { params: Promise<{ id: string }> }) {
  const { id } = await params;
  return <MarketDetail id={id} />;
}
